mapper.select:
SELECT X.BUYER_NAME ,X.BUYER_CODE ,X.SELLER_NAME ,X.SELLER_CODE ,X.IRS_NO ,X.ADDRESS ,X.AVL_FLAG ,X.APPROVAL_FLAG ,DECODE(X.APPROVAL_FLAG, 'Y', '품의완료', '품의대상') AS APPROVAL_TEXT ,X.SG_CNT FROM ( SELECT MAX(B.COM_NAME_LOC) AS BUYER_NAME ,B.COM_CODE AS BUYER_CODE ,MAX(C.COM_NAME_LOC) AS SELLER_NAME ,C.COM_CODE AS SELLER_CODE ,MAX(C.IRS_NO) AS IRS_NO ,MAX(C.ADDRESS_LOC) AS ADDRESS ,MAX(C.AVL_FLAG) AS AVL_FLAG ,MIN(S.APPROVAL_FLAG) AS APPROVAL_FLAG ,COUNT(*) AS SG_CNT FROM DSS_S_BUYER_RESULT S, ICOMCMPY C, ICOMCMPY B WHERE S.BUYER = B.COM_CODE AND S.AGENT = C.COM_CODE AND B.STATUS IN ('C','R') AND C.STATUS IN ('C','R') AND S.STATUS <> 'S'
AND S.BUYER = #{st_buyer_code}
AND S.AGENT = #{st_seller_code}
GROUP BY B.COM_CODE, C.COM_CODE ) X
WHERE X.APPROVAL_FLAG = #{st_approval_flag}
